<?php
require_once __DIR__.'/../includes/functions.php';require_role('student');
$q=db()->prepare('SELECT student_id,roll_number,department,semester FROM students WHERE user_id=?');$q->execute([current_user()['user_id']]);$student=$q->fetch();if(!$student){include __DIR__.'/../includes/header.php';echo '<div class="alert alert-warning">Your student profile has not been configured. Contact the administrator.</div>';include __DIR__.'/../includes/footer.php';exit;}
$sql='SELECT e.exam_id,e.exam_name,e.academic_session,e.exam_type,sub.subject_name,m.obtained_marks,m.total_marks FROM marks m JOIN exams e ON e.exam_id=m.exam_id JOIN subjects sub ON sub.subject_id=m.subject_id WHERE m.student_id=? ORDER BY e.exam_id DESC,sub.subject_name';$q=db()->prepare($sql);$q->execute([$student['student_id']]);$rows=$q->fetchAll();include __DIR__.'/../includes/header.php';?>
<div class="result-banner mb-4"><div class="small opacity-75">STUDENT RESULT PROFILE</div><div class="big"><?=e(current_user()['name'])?></div><div class="opacity-75"><?=e($student['roll_number'])?> · <?=e($student['department'])?> · Semester <?=e((string)$student['semester'])?></div></div>
<div class="card"><div class="card-header d-flex justify-content-between align-items-center"><span>Examination results</span><button class="btn btn-sm btn-outline-primary no-print" onclick="window.print()"><i class="bi bi-printer me-1"></i> Print / Save PDF</button></div><div class="card-body"><?php if(!$rows):?><div class="empty-state"><i class="bi bi-journal-x fs-2"></i><p class="mt-2 mb-0">No result records are available yet.</p></div><?php else:$groups=[];foreach($rows as $r)$groups[$r['exam_id']][]=$r;foreach($groups as $group):$obt=array_sum(array_column($group,'obtained_marks'));$max=array_sum(array_column($group,'total_marks'));$pct=$max?($obt/$max*100):0;?><div class="mb-4"><div class="d-flex justify-content-between align-items-center mb-2"><div><strong><?=e($group[0]['exam_name'])?></strong><div class="small text-secondary"><?=e($group[0]['exam_type'].' · '.$group[0]['academic_session'])?></div></div><span class="badge <?=result_status($pct)==='Pass'?'text-bg-success':'text-bg-danger'?>"><?=result_status($pct)?></span></div><div class="table-responsive"><table class="table"><thead><tr><th>Subject</th><th>Obtained</th><th>Maximum</th><th>Percentage</th><th>Grade</th></tr></thead><tbody><?php foreach($group as $r):$p=$r['total_marks']?($r['obtained_marks']/$r['total_marks']*100):0;?><tr><td><?=e($r['subject_name'])?></td><td><?=e((string)$r['obtained_marks'])?></td><td><?=e((string)$r['total_marks'])?></td><td><?=number_format($p,2)?>%</td><td><span class="badge badge-soft"><?=e(grade_for($p))?></span></td></tr><?php endforeach;?></tbody></table></div><div class="d-flex gap-4 flex-wrap small"><span>Total: <strong><?=number_format($obt,2)?> / <?=number_format($max,2)?></strong></span><span>Percentage: <strong><?=number_format($pct,2)?>%</strong></span><span>Overall grade: <strong><?=e(grade_for($pct))?></strong></span></div></div><hr><?php endforeach;endif;?></div></div>
<?php include __DIR__.'/../includes/footer.php';?>